package com.paytrace.webhook;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="webhook_inbox_events") public class WebhookInboxEntity { @Id private UUID id; @Column(name="provider_event_id",nullable=false) private String providerEventId; @Column(name="payment_id",nullable=false) private UUID paymentId; @Column(name="payload_hash",nullable=false) private String payloadHash; @Column(name="received_at",nullable=false) private Instant receivedAt; @Column(name="occurred_at",nullable=false) private Instant occurredAt; @Column(name="processing_status",nullable=false) private String processingStatus; @Column(name="duplicate_event",nullable=false) private boolean duplicate; @Column(name="processed_at") private Instant processedAt; protected WebhookInboxEntity(){} public WebhookInboxEntity(String providerEventId,UUID paymentId,String payloadHash,Instant occurredAt,boolean duplicate){id=UUID.randomUUID();this.providerEventId=providerEventId;this.paymentId=paymentId;this.payloadHash=payloadHash;this.occurredAt=occurredAt;receivedAt=Instant.now();processingStatus=duplicate?"DUPLICATE":"PROCESSED";this.duplicate=duplicate;processedAt=Instant.now();} public boolean duplicate(){return duplicate;} }
